From 030136b50b3356b5ae945879190b8bf28e41c427 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:37:06 +0100
Subject: [PATCH] plasmoid: share presentation mode state between applet
 instances

Each Display Configuration widget kept its own presentation mode state, so
enabling it in one left the switch off in every other one. Store the state
in the applet class, shared by all instances, and bind the switches to it.

BUG: 426426
---
 plasmoid/PresentationModeItem.qml |  4 ++++
 plasmoid/kscreenapplet.cpp        | 23 ++++++++++++++++++++++-
 plasmoid/kscreenapplet.h          | 11 +++++++++++
 plasmoid/main.qml                 |  5 +++--
 4 files changed, 40 insertions(+), 3 deletions(-)

diff --git a/plasmoid/PresentationModeItem.qml b/plasmoid/PresentationModeItem.qml
index 8d296797..fc702874 100644
--- a/plasmoid/PresentationModeItem.qml
+++ b/plasmoid/PresentationModeItem.qml
@@ -19,6 +19,8 @@ ColumnLayout {

     property alias checked: presentationModeSwitch.checked

+    signal toggled()
+
     spacing: Kirigami.Units.smallSpacing

     PlasmaComponents3.Switch {
@@ -29,6 +31,8 @@ ColumnLayout {
         text: i18n("Enable Presentation Mode")

         onToggled: {
+            root.toggled();
+
             // disable Switch while job is running
             enabled = false;

diff --git a/plasmoid/kscreenapplet.cpp b/plasmoid/kscreenapplet.cpp
index b48b785d..4b2c37c9 100644
--- a/plasmoid/kscreenapplet.cpp
+++ b/plasmoid/kscreenapplet.cpp
@@ -24,9 +24,13 @@ K_PLUGIN_CLASS_WITH_JSON(KScreenApplet, "metadata.json")
 KScreenApplet::KScreenApplet(QObject *parent, const KPluginMetaData &data, const QVariantList &args)
     : Plasma::Applet(parent, data, args)
 {
+    s_applets.append(this);
 }

-KScreenApplet::~KScreenApplet() = default;
+KScreenApplet::~KScreenApplet()
+{
+    s_applets.removeOne(this);
+}

 void KScreenApplet::init()
 {
@@ -48,6 +52,23 @@ int KScreenApplet::connectedOutputCount() const
     return m_connectedOutputCount;
 }

+bool KScreenApplet::presentationModeEnabled() const
+{
+    return s_presentationModeEnabled;
+}
+
+void KScreenApplet::setPresentationModeEnabled(bool enabled)
+{
+    if (s_presentationModeEnabled == enabled) {
+        return;
+    }
+
+    s_presentationModeEnabled = enabled;
+    for (KScreenApplet *applet : std::as_const(s_applets)) {
+        Q_EMIT applet->presentationModeEnabledChanged();
+    }
+}
+
 void KScreenApplet::applyLayoutPreset(KScreen::OsdAction::Action action)
 {
     KScreen::OsdAction::applyAction(m_screenConfiguration, action);
diff --git a/plasmoid/kscreenapplet.h b/plasmoid/kscreenapplet.h
index fc5b2a0e..86d5ac79 100644
--- a/plasmoid/kscreenapplet.h
+++ b/plasmoid/kscreenapplet.h
@@ -31,6 +31,10 @@ class KScreenApplet : public Plasma::Applet
      */
     Q_PROPERTY(int connectedOutputCount READ connectedOutputCount NOTIFY connectedOutputCountChanged FINAL)
     Q_PROPERTY(QVariant availableActions READ availableActions CONSTANT STORED false FINAL)
+    /**
+     * Whether presentation mode was enabled from any instance of this applet
+     */
+    Q_PROPERTY(bool presentationModeEnabled READ presentationModeEnabled WRITE setPresentationModeEnabled NOTIFY presentationModeEnabledChanged FINAL)

 public:
     explicit KScreenApplet(QObject *parent, const KPluginMetaData &data, const QVariantList &args);
@@ -40,16 +44,23 @@ public:

     int connectedOutputCount() const;

+    bool presentationModeEnabled() const;
+    void setPresentationModeEnabled(bool enabled);
+
     Q_INVOKABLE void applyLayoutPreset(KScreen::OsdAction::Action action);

     static QVariant availableActions();

 Q_SIGNALS:
     void connectedOutputCountChanged();
+    void presentationModeEnabledChanged();

 private:
     void checkOutputs();

     KScreen::ConfigPtr m_screenConfiguration;
     int m_connectedOutputCount = 0;
+
+    static inline QList<KScreenApplet *> s_applets;
+    static inline bool s_presentationModeEnabled = false;
 };
diff --git a/plasmoid/main.qml b/plasmoid/main.qml
index 326027db..52a5201f 100644
--- a/plasmoid/main.qml
+++ b/plasmoid/main.qml
@@ -28,7 +28,7 @@ PlasmoidItem {
     readonly property string kcmName: "kcm_kscreen"
     readonly property bool kcmAllowed: KConfig.KAuthorized.authorizeControlModule("kcm_kscreen")

-    property bool presentationModeEnabled: false
+    readonly property bool presentationModeEnabled: Plasmoid.presentationModeEnabled // qmllint disable missing-property

     P5Support.DataSource {
         id: pmSource
@@ -89,7 +89,8 @@ PlasmoidItem {
             Layout.topMargin: Kirigami.Units.smallSpacing * 2
             Layout.leftMargin: Kirigami.Units.smallSpacing
             Layout.rightMargin: Kirigami.Units.smallSpacing
-            onCheckedChanged: root.presentationModeEnabled = checked
+            checked: root.presentationModeEnabled
+            onToggled: Plasmoid.presentationModeEnabled = checked // qmllint disable missing-property
         }

         // compact the layout
